```python
def add_dict(dict1, dict2):
    # Create a new dictionary to store the combined results
    combined_dict = {}

    # Add all items from the first dictionary to the combined dictionary
    for key, value in dict1.items():
        combined_dict[key] = value

    # Add all items from the second dictionary to the combined dictionary
    for key, value in dict2.items():
        # If the key is already in the combined dictionary, add the values
        if key in combined_dict:
            combined_dict[key] += value
        else:
            # If the key is not in the combined dictionary, add the key-value pair
            combined_dict[key] = value

    return combined_dict

